   292	\text{st}(x) & = & \begin{cases}
   293				\lbrack x \rbrack + 1   \quad \text{if} \quad x \geq 0 \\
   294				\lbrack x \rbrack \quad \quad \;\;\, \text{if} \quad x < 0
   295	                   \end{cases}, \nonumber \\
   296	m_0(x)       & = & \text{st}(x) - \frac{1}{2}, \nonumber \\
   297	\zeta(x)     & = & x - m_0(x). \nonumber
   298	\end{eqnarray}
   299	These functions are presented in figure 1.
   300	\begin{figure}[ht]
   301	\begin{center}
   302	\includegraphics{fcts.ps}
   303	\caption{{\em Functions (a) $[z]$, (b) $\rm{st}$$(z)$, (c) $m_0(z)$ and (d) $\zeta(z)$}.}
   304	\end{center}
   305	\end{figure} 
   306	
   307	
   308	It can easily be checked that they satisfy the following properties
   309	\begin{eqnarray}\label{fctprop}
   310	m_0(z+1)   & = & m_0(z) + 1, \nonumber \\
   311	m_0(-z)    & = & - m_0(z),   \nonumber \\
   312	\zeta(z+1) & = & \zeta(z),             \\
   313	\zeta(-z)  & = & - \zeta(z), \nonumber \\
   314	-\frac{1}{2} < & \zeta(z) & < \frac{1}{2}. \nonumber 
   315	\end{eqnarray}
   316	Defining
   317	\begin{equation}
   318	b_{m,2} = \tilde{A}_m, \quad\quad d_{m,2} = \tilde{A}_{-m} \quad \quad \text{for} \quad m\geq \frac{1}{2},
   319	\end{equation}
   320	we finally have
   321	\begin{equation}\label{vpmq}
   322	\vp_2 = \frac{e^{i\frac{m_0(z_3) \pi}{L} x^-}}{\sqrt{4\pi}} 
   323	        \sum_{m=\frac{1}{2}}^\infty \left(
   324			u_{m,2} b_{m,2} e^{-i\frac{m \pi}{L} x^-} + v_{m,2} d_{m,2}^\dagger e^{i\frac{m \pi}{L} x^-}
   325					    \right)
   340	\end{equation}
   341	while other commutators vanish.
   342	
   343	Our last task in this section is to quantize the four remaining fields $\vp_4$, $\vp_5$, $\vp_6$, $\vp_7$. Equations \eqref{phicomp} teach us that we may quantize them by performing the replacements shown in Table 1.
   344	
   345	\begin{table}[ht]
   346	\begin{center}
   347	\begin{tabular}{| c | c |}
   348	\hline
   349	Field & Functions \\
   350	\hline
   351	\hline
   352	$\vp_1 \rightarrow \vp_5$ & $m_{0,1}=m_{0,2}\equiv m_0(z_3) \rightarrow m_{0,4}=m_{0,5}\equiv m_0(-\frac{z_3}{2}-z_8)$ \\
   353	$\vp_2 \rightarrow \vp_4$ & $\zeta_1=\zeta_2\equiv\zeta(z_3) \rightarrow \zeta_4=\zeta_5\equiv\zeta(-\frac{z_3}{2}-z_8)$\\
   354	\hline
   355	$\vp_1 \rightarrow \vp_6$ & $m_{0,1}=m_{0,2}\equiv m_0(z_3) \rightarrow m_{0,6}=m_{0,7}\equiv m_0(-\frac{z_3}{2}+z_8)$ \\
   356	$\vp_2 \rightarrow \vp_7$ & $\zeta_1=\zeta_2\equiv\zeta(z_3) \rightarrow \zeta_6=\zeta_7\equiv\zeta(-\frac{z_3}{2}+z_8)$\\
   357	\hline
   358	\end{tabular}
   359	\end{center}
   360	\caption{Replacements to perform for obtaining $\vp_4, \vp_5, \vp_6$ and $\vp_7$ from $\vp_1$ and $\vp_2$.}
   361	\end{table}
   362	
   363	Let us now summarize all informations obtained from quantization.
   364	
   365	\begin{eqnarray*}
   366	\vp_j & = & \frac{a_{0,j}}{\sqrt{4\pi}} 
   367	          + \sum_{n=1}^\infty \frac{w_n}{\sqrt{4\pi}} \left(
   368		          a_{n,j} e^{-i\frac{n\pi}{L}x^-}
   369		        + a_{n,j}^\dagger e^{i\frac{n\pi}{L}x^-} \right)
   370	\quad \quad \quad \quad \quad \quad \: \, j=3,8,\\
   371	\vp_k & = & \frac{e^{im_{0,k}\frac{\pi}{L}x^-}}{\sqrt{4\pi}}
   372	            \sum_{m=\frac{1}{2}}^\infty \left(
   373	                  u_{m,k} b_{m,k} e^{-i\frac{m\pi}{L}x^-}
   374	                + v_{m,k} d_{m,k}^\dagger e^{i\frac{m\pi}{L}x^-} \right)
   375	\quad \quad \quad k=2,4,7, \\
   376	\vp_1 & = & \vp_2^\dagger, \\
   377	\vp_5 & = & \vp_4^\dagger, \\
   378	\vp_6 & = & \vp_7^\dagger,
   379	\end{eqnarray*}
   380	with
   381	\begin{eqnarray*}
   382	w_n & = & \frac{1}{\sqrt{n}}, \\
   383	u_{m,k} & = & \frac{1}{\sqrt{m+\zeta_k}}, \quad\quad\quad k=1,2,4,5,6,7,\\
   384	v_{m,k} & = & \frac{1}{\sqrt{m-\zeta_k}}, \quad\quad\quad k=1,2,4,5,6,7,
   385	\end{eqnarray*}
   386	
   387	The only non-null commutators, except those involving the zero-modes, are
   388	\begin{eqnarray*}
   389	\left \lbrack a_{k,i}, a_{l,j}^\dagger \right \rbrack & = & \delta_{kl} \delta_{ij},\\
   390	\left \lbrack b_{m,i}, b_{n,j}^\dagger \right \rbrack & = & \delta_{mn} \delta_{ij},\\

