import numpy as np, math, time

def m0(x):
 st=math.floor(x)+(1 if x>=0 else 0)
 return st-.5

def zz(x):return x-m0(x)
def v0(u,v,N):
 z=[zz(u),zz(-v),zz(v-u)]; M=m0(u)+m0(-v)+m0(v-u)
 q=np.arange(N)+.5
 k=q[:,None];m=q[None,:]
 s1=sum(np.sum((k-m-2*a)**2/((k+m)**2*(m+a)*(k-a))) for a in z)
 s2=0.
 for a in z:
  for im,mv in enumerate(q):
   kv=q[im+1:]
   s2+=np.sum(((kv-2*mv+a)/((kv-a)**2*(mv-a))+(kv-2*mv-a)/((kv+a)**2*(mv+a)))/(kv-mv))
 def f(a,b,c):
  n=q[None,:];m=q[:,None]
  return np.sum((m-n+c-b)**2/((m+n+a+M)**2*(m-b)*(n-c))+(m-n-c+b)**2/((m+n-a-M)**2*(m+b)*(n+c)))
 s3=f(z[0],z[1],z[2])+f(z[1],z[2],z[0])+f(z[2],z[0],z[1])
 return s1+s2+s3

def project(N,G=18):
 A=[];Y=[];W=[]
 for i in range(G):
  u=(i+.5)/G
  for j in range(G):
   v=(j+.5)/G
   ph=[2*math.pi*(2*u-v)/3,2*math.pi*(2*v-u)/3,-2*math.pi*(u+v)/3]
   t=sum(np.exp(1j*np.array(ph)))
   chi8=abs(t)**2-1; ret3=(t**3).real
   roots=[2*math.pi*u,2*math.pi*v,2*math.pi*(v-u)]
   jac=64*np.prod([math.sin(x/2)**2 for x in roots]);w=jac/3
   A.append([1,chi8,ret3]);Y.append(v0(u,v,N));W.append(w)
 A=np.array(A);Y=np.array(Y);W=np.array(W)
 gram=A.T@(W[:,None]*A);rhs=A.T@(W*Y);coef=np.linalg.solve(gram,rhs);res=np.sqrt(np.sum(W*(Y-A@coef)**2)/np.sum(W))
 return coef,res,Y.min(),Y.max(),np.linalg.cond(gram)
for N in (6,10,16,24,32):
 t=time.time();print(N,project(N),time.time()-t)
