import numpy as np,math,time
from numpy.polynomial.legendre import leggauss

def m0(x):return math.floor(x)+(1 if x>=0 else 0)-.5
def z(x):return x-m0(x)
def V(u,v,N):
 Z=[z(u),z(-v),z(v-u)];M=m0(u)+m0(-v)+m0(v-u);q=np.arange(N)+.5;k=q[:,None];m=q[None,:]
 s=sum(np.sum((k-m-2*a)**2/((k+m)**2*(m+a)*(k-a))) for a in Z)
 for a in Z:
  for ii,mv in enumerate(q):
   kv=q[ii+1:];s+=np.sum(((kv-2*mv+a)/((kv-a)**2*(mv-a))+(kv-2*mv-a)/((kv+a)**2*(mv+a)))/(kv-mv))
 def f(a,b,c):
  mm=q[:,None];nn=q[None,:];return np.sum((mm-nn+c-b)**2/((mm+nn+a+M)**2*(mm-b)*(nn-c))+(mm-nn-c+b)**2/((mm+nn-a-M)**2*(mm+b)*(nn+c)))
 return s+f(Z[0],Z[1],Z[2])+f(Z[1],Z[2],Z[0])+f(Z[2],Z[0],Z[1])
def calc(N,eps,G):
 x,w=leggauss(G);x=(x+1)/2;w/=2;A=[];Y=[];W=[]
 for i,u in enumerate(x):
