   rd=min(abs(np.sin(np.pi*u)),abs(np.sin(np.pi*v)),abs(np.sin(np.pi*(v-u))))
   if rd<eps:continue
   J=64*np.sin(np.pi*u)**2*np.sin(np.pi*v)**2*np.sin(np.pi*(v-u))**2
   ph=np.array([2*np.pi*(u+v)/3,2*np.pi*(-2*u+v)/3,2*np.pi*(u-2*v)/3]);t=np.exp(1j*ph).sum()
   A.append([1,abs(t)**2-1,(t**3).real]);Y.append(V(u,v,N));W.append(w[i]*w[j]*J/6)
 A=np.array(A);Y=np.array(Y);W=np.array(W);M=A.T@(W[:,None]*A);c=np.linalg.solve(M,A.T@(W*Y));res=np.sqrt(np.sum(W*(Y-A@c)**2)/sum(W));return c,res,sum(W),np.linalg.cond(M),len(Y)
for G in (20,28,36):
 for e in (.08,.05,.03):
  for N in (32,64,128,256):
   t=time.time();c,r,norm,cond,n=calc(N,e,G);print(G,e,N,*[round(q,6) for q in c],round(r,4),round(norm,7),round(cond,3),n,round(time.time()-t,2))
